import type { DimensionType } from './catalog';

/**
 * Result of running a view spec against a data mart.
 * Numbers come only from the query engine; the SQL is generated by the
 * deterministic compiler (never by an LLM) and returned for audit.
 */

export type ResultColumnKind = 'dimension' | 'metric';

export interface ResultColumn {
  id: string;
  label: string;
  kind: ResultColumnKind;
  type: DimensionType;
}

export type ResultCell = string | number | null;

export type ViewResultWarningCode = 'MISSING_BUSINESS_DATES' | 'TRUNCATED' | 'METRIC_NOT_CERTIFIED';

export interface ViewResultWarning {
  code: ViewResultWarningCode;
  message: string;
}

export interface ViewResult {
  martId: string;
  columns: ResultColumn[];
  rows: Record<string, ResultCell>[];
  /** True when the result had more rows than the limit and was cut. */
  truncated: boolean;
  /** SQL generated by the compiler, with positional parameters. */
  sql: string;
  params: (string | number)[];
  businessDates: {
    /** Weekdays (Monday to Friday) in the requested period. */
    requestedWeekdays: number;
    /** Business dates in the period that have data in the mart. */
    withData: string[];
    /** Weekdays in the period without any data: the mart may not have been processed. */
    missingWeekdays: string[];
  };
  warnings: ViewResultWarning[];
}
